HTML+='function renderList(){let list=document.getElementById("sideList");if(!allChats.length){list.innerHTML="<div class=\'side-empty\'>No chats yet.<br>Tap New Chat to start.</div>";return;}list.innerHTML="";allChats.slice().reverse().forEach(c=>{let div=document.createElement("div");div.className="side-item"+(c.id===curId?" active":"");let ic=document.createElement("span");ic.className="ic";ic.textContent="💬";let mid=document.createElement("div");let b=document.createElement("b");b.textContent=c.title||"New Chat";let sm=document.createElement("small");sm.textContent=new Date(c.time).toLocaleString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});mid.appendChild(b);mid.appendChild(sm);let del=document.createElement("span");del.className="side-del";del.textContent="×";del.onclick=(e)=>{e.stopPropagation();allChats=allChats.filter(x=>x.id!==c.id);if(curId===c.id)newChat(true);saveChats();renderList();};div.appendChild(ic);div.appendChild(mid);div.appendChild(del);div.onclick=()=>{openChat(c.id);closeSide();};list.appendChild(div);});}'
