HTML+='function openChat(id){let c=allChats.find(x=>x.id===id);if(!c)return;curId=id;chat.innerHTML="";if(!c.msgs.length){welcome.style.display="flex";chat.style.display="none";started=false;}else{welcome.style.display="none";chat.style.display="flex";started=true;c.msgs.forEach(m=>{addMsgOnly(m.text||"",m.w||"jarvis",m.ts||m.time||Date.now());});}renderList();inp.blur();}'
HTML+='function buildVoiceSel(){let s=document.createElement("select");s.className="voice-sel";s.title="Change voice";let o=document.createElement("option");o.value="auto";o.textContent="🎙️ Auto";s.appendChild(o);try{(speechSynthesis.getVoices()||[]).slice(0,12).forEach(v=>{let op=document.createElement("option");op.value=v.name;op.textContent=(v.lang||"")+" "+(v.name||"").replace("Google ","").replace("Microsoft ","").slice(0,14);s.appendChild(op);});}catch(e){}s.onchange=()=>{let n=s.value;if(n==="auto"){voiceMode="auto";pickBestVoice();}else{let f=voiceList.find(v=>v.name===n);if(f){voiceCache=f;voiceMode="manual";}}showToast("Voice changed");};s.onclick=(e)=>{e.stopPropagation();};return s;}'
HTML+='function addMsgOnly(t,w,ts){let d=document.createElement("div");d.className="msg "+w;let l="JARVIS";if(w!=="jarvis"){l="YOU - Dev Sir";}let head=document.createElement("div");head.className="msg-head";let small=document.createElement("small");small.textContent=l;let tm=document.createElement("span");tm.className="msg-time";tm.textContent=nowTime(ts||Date.now());head.appendChild(small);head.appendChild(tm);let sp=document.createElement("span");sp.className="msg-text";sp.textContent=t;let act=document.createElement("div");act.className="actions";let cp=document.createElement("button");cp.innerHTML=`<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="12" height="12" rx="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>`;cp.title="Copy";cp.type="button";cp.onclick=()=>copyBtn(cp);act.appendChild(cp);if(w==="jarvis"){let spk=document.createElement("button");spk.innerHTML=`<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M15.54 8.46a5 5 0 0 1 0 7.07"></path><path d="M19.07 4.93a10 10 0 0 1 0 14.14"></path></svg>`;spk.title="Listen";spk.type="button";spk.onclick=()=>speakBtn(spk);act.appendChild(spk);act.appendChild(buildVoiceSel());}d.appendChild(head);d.appendChild(sp);d.appendChild(act);chat.appendChild(d);chat.scrollTop=chat.scrollHeight;return sp;}'
HTML+='function addMsg(t,w,ts){let t2=ts||Date.now();let s=addMsgOnly(t,w,t2);if(curId){let c=allChats.find(x=>x.id===curId);if(c){c.msgs.push({text:t,w:w,ts:t2});if(c.msgs.length===1&&w==="you"){c.title=t.slice(0,35);}c.time=Date.now();saveChats();renderList();}}return s;}'
HTML+='function typewriter(span,txt,replyTs){if(typingTimer)clearInterval(typingTimer);let i=0;span.innerHTML="";let cur=document.createElement("span");cur.className="tw-cursor";span.appendChild(cur);let speed=txt.length>1200?2:txt.length>600?8:15;let step=txt.length>1200?4:txt.length>600?2:1;typingTimer=setInterval(()=>{i+=step;let shown=txt.slice(0,i);span.textContent="";let t=document.createTextNode(shown);span.appendChild(t);span.appendChild(cur);chat.scrollTop=chat.scrollHeight;if(i>=txt.length){clearInterval(typingTimer);typingTimer=null;span.textContent=txt;if(curId){let c=allChats.find(x=>x.id===curId);if(c){c.msgs.push({text:txt,w:"jarvis",ts:replyTs});c.time=Date.now();saveChats();renderList();}}}},speed);}'
HTML+='renderList();'
HTML+='async function send(){let q=inp.value.trim();if(!q||busy)return;busy=true;sendBtn.disabled=true;if(!curId){curId=Date.now().toString();allChats.push({id:curId,title:q.slice(0,35),time:Date.now(),msgs:[]});saveChats();}if(!started){started=true;welcome.style.display="none";chat.style.display="flex";}inp.value="";inp.blur();addMsg(q,"you",Date.now());typing.classList.add("show");typing.style.display="flex";chat.scrollTop=chat.scrollHeight;try{let ctrl=new AbortController();let to=setTimeout(()=>ctrl.abort(),20000);let r=await fetch("/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:q,lang:lang}),signal:ctrl.signal});clearTimeout(to);if(!r.ok)throw new Error("Server "+r.status);let d=await r.json();typing.classList.remove("show");typing.style.display="none";let replyTs=Date.now();let span=addMsgOnly("","jarvis",replyTs);let txt=d.reply||"Server is busy. Please try again.";typewriter(span,txt,replyTs);}catch(e){typing.classList.remove("show");typing.style.display="none";addMsg("Connection issue. Please try again.","jarvis",Date.now());}finally{busy=false;sendBtn.disabled=false;inp.blur();}}'
HTML+='inp.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();send();}});'
HTML+='chat.addEventListener("click",()=>{inp.blur();});welcome.addEventListener("click",()=>{inp.blur();});document.addEventListener("click",e=>{if(!e.target.closest(".input-area")){inp.blur();}},true);'
