class H(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  self.send_response(200);self.send_header("Content-type","text/html; charset=utf-8");self.send_header("Cache-Control","no-cache");self.end_headers();self.wfile.write(HTML.encode('utf-8'))
 def do_POST(self):
  try:
   ln=int(self.headers.get('Content-Length',0) or 0)
   if ln<=0 or ln>50000:raise ValueError("bad length")
   body=json.loads(self.rfile.read(ln).decode('utf-8'));rep=get_reply(body.get("message",""),body.get("lang","english"))
  except Exception as e:rep=f"Dev Sir, request me problem aa gayi. ({e})"
  out=json.dumps({"reply":rep},ensure_ascii=False).encode('utf-8');self.send_response(200);self.send_header("Content-type","application/json; charset=utf-8");self.send_header("Content-Length",str(len(out)));self.end_headers();self.wfile.write(out)
 def log_message(self,format,*args):return
socketserver.TCPServer.allow_reuse_address=True
socketserver.TCPServer.daemon_threads=True
print("JARVIS START - PORT "+str(PORT))
with socketserver.TCPServer(("0.0.0.0",PORT),H) as s:
 try:s.serve_forever()
 except KeyboardInterrupt:pass
